        uint256 ownerBefore = owner.balance;

        // make the call from caller to c.go(), but we need c to call the reverter address.
        // The contract C in src expects a hard-coded target; to route through our reverter,
        // we will deploy a proxy that forwards to the reverter address by making the low-level call
        // from the caller: since C's go() uses a hardcoded target, we cannot change it here.
        // However, the distinguishing behaviour only requires that the forwarded low-level call fails,
        // which triggers the remaining balance to be transferred to owner vs msg.sender.
        // To simulate that, we first send Ether into c so that after the failed external call there is
        // a non-zero balance to forward.

        // fund contract c with some leftover balance before calling go
        vm.deal(address(this), 1 ether);
        // send some Ether into c via its fallback
        (bool sent,) = address(c).call{value: 0.5 ether}("");
