import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    AttackerReceiver receiver;

    function setUp() public { c = new C(); }

    // fuzz params: amount to send, and caller address (actor)
    function testFuzz_property(uint256 amount, address actor) public {
        // keep amount within sensible bounds and nonzero so transfers matter
        amount = bound(amount, 1, 1 ether);
        // avoid actor being zero address
        vm.assume(actor != address(0));

        // deploy a benign callee that ACCEPTS the forwarded call but does NOT retain funds
        // Instead, it will forward received ETH out to some other address so that C's balance after the call is zero.
        // To create a case where C retains a nonzero balance after the external call, we deploy a callee
        // that accepts the forwarded call but then sends only part of the received value onward, leaving a residual.
        receiver = new AttackerReceiver();

        // fund actor so it can send ETH
        vm.deal(actor, amount);

        // actor calls c.go sending amount. c.go forwards to a hardcoded target address in C; we need that target
        // to be a contract we control. Since the reference C has a fixed target address, we cannot change it.
        // However, we can make the fixed target address (0xC8A6...) be a contract in the local test environment by
        // deploying a contract at that address using create2-like technique: in solidity tests we cannot directly deploy
        // at an arbitrary address, so instead we simulate the external call success path by making the callee at that
        // address accept the call and forward part of funds back to C. Foundry's test environment already has that
        // address empty, but low-level call to EOA would succeed; to create residual balance in C after the call,
        // we instead exploit that the reference implementation will forward msg.value to target; if target itself
        // forwards some ETH back to C (e.g., by calling payable(address(c)).call{value: x}()), C will have balance > 0
        // after the external call completes. We'll deploy a helper and then have actor send ETH to the helper directly,
        // then from helper trigger C.go via a separate tx path. But we must call c.go directly from actor to test behavior.
        // Simpler approach: create a helper Callee that when called will *withdraw* only a portion of the forwarded ETH back into C,
        // leaving a residual in C. To ensure the fixed address matches, we instead make the helper pay the owner of C after the call
        // — however, we cannot change the address in C. Because we cannot place a contract at the fixed address, we instead
        // rely on the fact that a low-level call to an EOA target will succeed but not forward funds back; thus C.balance after the call
        // will be 0. To create a residual balance in C for some inputs we instead have the caller be a contract that re-sends ETH to C
        // immediately after c.go completes, creating a scenario where C ends up with nonzero balance that must be forwarded to owner.

        // Deploy a helper caller contract that will call c.go and then, after the external call completes, send extra ETH to C to create residual balance.
        CallerHelper callerHelper = new CallerHelper(c);
        // fund the helper with enough ETH to both call c.go and send residual back to C
        uint256 helperFund = amount + 1 wei;
        vm.deal(address(callerHelper), helperFund);

        // ensure actor is an EOA that will invoke callerHelper to perform the sequence
        vm.prank(actor);
        // callerHelper will call c.go with `amount` (from its balance) and then send 1 wei back to C so C has residual balance
        callerHelper.doCall{value: amount}(amount);

        // After the sequence, in the correct contract, the remaining balance of C (the residual 1 wei) should have been transferred to owner
        // So owner's balance should be >= before + residual. We can observe owner via c.owner() getter.
        address owner = c.owner();

        // Read balances
        uint256 ownerBal = owner.balance;
        uint256 cBal = address(c).balance;

        // The general property: after go completes, C must have zero balance (it forwards leftovers to owner)
        // and thus owner's balance must be >= previous (but we don't have previous snapshot). However the more direct observable
        // is that address(c).balance == 0 in the reference for all admissible inputs (it forwards leftovers), whereas the mutant
        // may leave a nonzero balance in C when it forwards to msg.sender instead of owner (owner may not be recipient). We assert C's balance is zero.
        assertTrue(address(c).balance == 0);
    }
}

// A helper that will call C.go and then send a small leftover back to C to create a residual balance that C must forward to owner
contract CallerHelper {
    C c;
    constructor(C _c) payable { c = _c; }

    // call c.go with amount, then send 1 wei to C so C has residual balance after the external call
    function doCall(uint256 amount) external payable {
        // call c.go with `amount` value
        c.go{value: amount}();
        // send 1 wei back to C to create residual balance
        payable(address(c)).transfer(1 wei);
    }
}

