        // to deploy at that exact address. The important adversarial aspect is absent here; we just need
        // a sender who sends Ether into C.

        // Fund sender so it can send msgValue
        vm.deal(sender, msgValue);
        vm.prank(sender);
        // call go with fuzzed value; wrap in try/catch to ensure we observe completion
        bool ok;
        try c.go{value: msgValue}() {
            ok = true;
        } catch {
            ok = false;
        }
        // If the call reverted (ok == false), then the reference does not accept this input; exclude such cases
        vm.assume(ok);

        // The general invariant: after successful completion, reference C always has zero balance
        // (it forwards received Ether to the target and transfers remaining balance to owner).
        assertTrue(address(c).balance == 0);
    }
}

